import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { uv, vec3, mix, smoothstep } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, BufferGeometry, BufferAttribute, DirectionalLight, PlaneGeometry, OctahedronGeometry, Color, DoubleSide } = THREE;

  function colorToVec3(hexColor) {
    const c = new Color(hexColor);
    return vec3(c.r, c.g, c.b);
  }

  function createTriangularPrismGeometry(sideLength, length) {
    const h = sideLength * Math.sqrt(3) / 2;
    const hThird = h / 3;
    const halfLen = length / 2;

    const vertices = new Float32Array([
      // Front triangle (z = -halfLen)
      -sideLength / 2, -hThird, -halfLen,
      sideLength / 2, -hThird, -halfLen,
      0, h - hThird, -halfLen,
      // Back triangle (z = halfLen)
      -sideLength / 2, -hThird, halfLen,
      sideLength / 2, -hThird, halfLen,
      0, h - hThird, halfLen
    ]);

    const indices = new Uint32Array([
      // Front face
      0, 2, 1,
      // Back face
      3, 4, 5,
      // Bottom
      0, 1, 4, 0, 4, 3,
      // Right side
      1, 2, 5, 1, 5, 4,
      // Left side
      2, 0, 3, 2, 3, 5
    ]);

    const geo = new BufferGeometry();
    geo.setAttribute('position', new BufferAttribute(vertices, 3));
    geo.setIndex(new BufferAttribute(indices, 1));
    geo.computeVertexNormals();

    return geo;
  }

  const group = new Group();
  const disposables = [];
  const timelines = [];

  const palette = {
    bg: '#0b0b10',
    surface: '#101017',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38'
  };

  // Backdrop plane with gradient stops
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(
    colorToVec3(palette.bg),
    mix(
      colorToVec3('#12121a'),
      colorToVec3(palette.ink),
      smoothstep(0.6, 1, uv().y)
    ),
    smoothstep(0, 0.6, uv().y)
  );

  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.z = -2.5;
  group.add(backdropMesh);
  disposables.push(backdropGeo, backdropMat);

  // Triangular prism with physical material
  const prismGeo = createTriangularPrismGeometry(1.2, 1.8);
  const prismMat = new MeshPhysicalNodeMaterial({
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480],
    roughness: 0.08,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    attenuationColor: new Color(palette.paper),
    attenuationDistance: 2.5,
    side: DoubleSide
  });

  const prismMesh = new Mesh(prismGeo, prismMat);
  prismMesh.rotation.z = Math.PI * 12 / 180;
  prismMesh.rotation.y = Math.PI * 20 / 180;
  group.add(prismMesh);
  disposables.push(prismGeo, prismMat);

  // Emissive octahedron core
  const coreGeo = new OctahedronGeometry(0.35);
  const coreMat = new MeshPhysicalNodeMaterial({
    color: new Color(palette.accent),
    emissive: new Color(palette.accent),
    emissiveIntensity: 2.2,
    metalness: 0.0,
    roughness: 0.3
  });
  const coreMesh = new Mesh(coreGeo, coreMat);
  group.add(coreMesh);
  disposables.push(coreGeo, coreMat);

  // Back rim light (cool directional)
  const rimLight = new DirectionalLight(0x6b8ab8, 1.0);
  rimLight.position.set(-2, 1, -3);
  group.add(rimLight);

  // Caustic streak plane with dispersed gradient
  const causticGeo = new PlaneGeometry(2.4, 0.5);
  const causticMat = new MeshBasicNodeMaterial();
  causticMat.colorNode = mix(
    colorToVec3(palette.accent),
    mix(
      colorToVec3(palette.paper),
      colorToVec3('#9fb0c4'),
      smoothstep(0.5, 0.8, uv().x)
    ),
    smoothstep(0.2, 0.5, uv().x)
  );
  causticMat.transparent = true;
  causticMat.opacity = 0.35;

  const causticMesh = new Mesh(causticGeo, causticMat);
  causticMesh.position.y = -1.1;
  causticMesh.rotation.x = -Math.PI / 2;
  group.add(causticMesh);
  disposables.push(causticGeo, causticMat);

  // Text: headline
  const headlineText = ctx.fontAtlas.createText('Light, machined.', {
    fontSize: 68,
    color: palette.paper,
    align: 'center'
  });
  headlineText.position.y = -1.75;
  group.add(headlineText);

  // Text: caption
  const captionText = ctx.fontAtlas.createText('SAPPHIRE OVER DIAL / ZERO DISTORTION', {
    fontSize: 18,
    color: palette.paper,
    align: 'center',
    letterSpacingPx: 1.44
  });
  captionText.position.y = -2.25;
  group.add(captionText);

  // Apply depth-rotate primitive for hover interaction
  let depthRotateCleanup = null;
  if (ctx.primitives && ctx.primitives['depth-rotate']) {
    const result = ctx.primitives['depth-rotate'](group, { maxDeg: 10 });
    if (result && result.cleanup) {
      depthRotateCleanup = result.cleanup;
    }
  }

  // Setup cleanup
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    if (depthRotateCleanup) depthRotateCleanup();
    disposables.forEach(d => {
      if (d && typeof d.dispose === 'function') {
        d.dispose();
      }
    });
  };

  return group;
}
